mapper.select:
SELECT
FROM education_achievements achievement JOIN course_operation_achievement_details detail ON detail.achievement_id = achievement.achievement_id JOIN users owner ON owner.user_id = achievement.teacher_user_id WHERE achievement.achievement_type = 'COURSE_OPERATION' AND achievement.deleted_yn = 'N'
ORDER BY achievement.achievement_date DESC, achievement.achievement_id DESC LIMIT #{criteria.safePageSize} OFFSET #{criteria.offset}

mapper.insert:
INSERT INTO course_operation_achievement_details (
    achievement_id,
    performance_detail
)
VALUES (
    #{achievementId},
    #{performanceDetails}
)

mapper.update:
UPDATE course_operation_achievement_details detail
SET performance_detail = #{performanceDetails}
WHERE detail.achievement_id = #{achievementId}
